# Code generated by Claude
"""
The minimal end-to-end MPVI pipeline (design plan 8, D3 + D4 skeleton): a full run to success, recorded and replayed.

    MUJOCO_GL=egl python experiments/mpvi_pipeline_test.py [--keep DIR]

The hand-written plan (go to the bench; pick up the beaker; place the beaker on the hotplate) goes through the orchestrator, the scripted staging, the scripted pick and place
with mink, and the oracle checker. Checks: the episode's outcome is SUCCESS, the plan finished with every segment done, the pick's close event was logged and the place's
open event decided (passed), the beaker ended on the hotplate, the left arm is back home and the gripper open, the status text showed every segment, and the recording replays
bit-identically.
"""

import argparse
import gc
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import MINK_CFG, TASK_CFG  # noqa: E402

sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
from episode_test_sources import make_clearance_monitor  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main(args):
    sim = load_task(cameras=True)
    task = make_pipeline_task()
    out = Path(args.keep) if args.keep else Path(tempfile.mkdtemp(prefix="mpvi_pipeline_"))
    for sub in ("episode", "recording"):                 # the recorder does not clear old chunk files: a longer earlier run would leave extra ticks in the replay
        shutil.rmtree(out / sub, ignore_errors=True)
    mon = {}

    def extra(m, d):
        mon["m"] = make_clearance_monitor(m, d)
        return {"clearance": mon["m"]}

    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording", extra_sources=extra)
    pipe = task["pipeline"]
    state = pipe["orchestrator"]["state"]
    rep = s.get("report", s)
    print(f"\noutcome {s['outcome']}  plan failure: {state['failure']}")
    check("the episode outcome is SUCCESS", s["outcome"] == "SUCCESS", s["outcome"])
    check("the plan finished and every segment is done", state["finished"] and all(x == "done" for x in state["status"]), str(state["status"]))
    v = state["verdicts"]
    check("the pick's close event was logged and the place's open event decided and passed",
          any(x["event"] == "gripper_closed" and not x["decides"] and x["passed"] for x in v) and any(x["event"] == "gripper_opened" and x["decides"] and x["passed"] for x in v),
          f"{[(x['event'], x['decides'], x['passed']) for x in v]}")
    m = sim.model
    q = sim.data.qpos[arm_ids(m, "left")["qadr"]]
    err = float(np.max(np.abs(q - np.array(TASK_CFG["home_q_left"]))))
    check("the left arm is back at home", err < 0.03, f"largest joint error {err:.4f} rad")
    fq = int(m.jnt_qposadr[arm_ids(m, "left")["finger_jnt"][0]])
    check("the gripper is open", sim.data.qpos[fq] > TASK_CFG.get("finger_open", 0.044) - 0.003, f"travel {1000 * sim.data.qpos[fq]:.1f} mm")
    ok, diag = task["check_success"](m, sim.data)
    check("the beaker stands on the hotplate", all(diag[k]["ok"] for k in ("a_xy_in_footprint", "b_height", "c_upright", "d_at_rest")), str({k: diag[k] for k in diag if k != "plan_finished"}))
    log = (out / "episode" / "episode_log.csv").read_text().splitlines()
    phases = {ln.split(",")[1] for ln in log[1:]}
    check("the status text showed every segment", all(any(f"{i}/3" in p for p in phases) for i in (1, 2, 3)), f"{len(phases)} distinct phase texts")
    check("grounding at dispatch: the pick acted on the beaker, the place on the beaker (the one in the hand) and the hotplate",
          state["grounded"] == [{"segment": 1, "manipulated": "beaker"}, {"segment": 2, "manipulated": "beaker", "destination": "hotplate"}], f"{state['grounded']}")
    glog = pipe["grounder"]["log"]
    check("the grounding log has one resolved entry per object phrase and no failure", [e["kind"] for e in glog] == ["resolved"] * 3, f"{[e['kind'] for e in glog]}")
    check("the tagged plan reaching the orchestrator carries the labels and an empty postprocess log (the keywords agreed)",
          task["tagged_plan"]["segments"][2]["primitive"] == "place" and task["tagged_plan"]["segments"][2]["check"] and task["tagged_plan"]["postprocess"]["log"] == [])
    wm = pipe["world"]
    hp, bk = wm.object_pose("hotplate")["position"], wm.object_pose("beaker")["position"]
    check("the world model's beaker entry (sim ground truth) ends on the hotplate and is not held", float(np.linalg.norm(bk[:2] - hp[:2])) < 0.05 and wm.get("beaker").properties["held_by"] is None
          and wm.get("beaker").found == "sim_ground_truth", f"{1000 * float(np.linalg.norm(bk[:2] - hp[:2])):.0f} mm from the hotplate centre, last seen {wm.get('beaker').last_seen:.1f} s")
    print("\nsmallest distances of the left arm's moving parts, per phase (m; the right arm, the bench and the hotplate)")
    arm_min = 9.0
    for ph, rec_ in mon["m"]["state"]["min"].items():
        if "PICK" in ph or "PLACE" in ph:
            print(f"  {ph:34s} other arm {rec_['other arm'][0]:.4f}  bench {rec_['bench'][0]:.4f}  hotplate+beaker {rec_['hotplate+beaker'][0]:.4f}")
            if "other arm" in rec_:
                arm_min = min(arm_min, rec_["other arm"][0])
    lim = MINK_CFG["min_distance"]["right_arm"]
    check("the arms stay at least the arm-to-arm limit apart (3 mm of servo lag allowed)", arm_min >= lim - 0.003, f"smallest {1000 * arm_min:.1f} mm, limit {1000 * lim:.0f} mm")
    print("\nreplay of the recording")
    del sim, task, pipe
    gc.collect()
    r = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", r["ok"], f"{r['ticks']} ticks, mismatch {r['mismatch']}")
    if not args.keep:
        shutil.rmtree(out, ignore_errors=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--keep", help="keep the episode log and the recording in this directory")
    main(ap.parse_args())
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)
